import { Geist, Geist_Mono, Montserrat } from "next/font/google";
import React, { type ReactNode } from "react";

import { cn } from "@/lib/utils";

import "@/app/tokens.css";
import "@/app/globals.css";

const GeistSans = Geist({
  subsets: ["latin"],
  variable: "--font-sans",
});

const GeistMono = Geist_Mono({
  subsets: ["latin"],
  variable: "--font-mono",
});

const MontserratSerif = Montserrat({
  subsets: ["latin"],
  variable: "--font-serif",
});

export default function RootLayout({
  children,
}: Readonly<{
  children: ReactNode;
}>) {
  return (
    <html
      lang="en"
      className={cn(
        GeistSans.variable,
        GeistMono.variable,
        MontserratSerif.variable,
        "bg-background text-foreground",
      )}
    >
      <body>
        <main className="mt-16 flex w-full justify-center">
          <div className="container">{children}</div>
        </main>
      </body>
    </html>
  );
}

"use client";

import { ReceiveComponent } from "@/components/receive/receive-component";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";

function ReceiveContent() {
  return (
    <div className="flex min-h-screen flex-col bg-background text-text w-full">
      <main className="flex-1 p-2 flex flex-col w-full">
        <div className="container mx-auto py-8">
          <Card className="bg-background border border-[#9945FF]/20 max-w-md mx-auto">
            <CardHeader>
              <CardTitle className="text-text">Receive</CardTitle>
            </CardHeader>
            <CardContent>
              <ReceiveComponent />
            </CardContent>
          </Card>
        </div>
      </main>
    </div>
  );
}

export default function ReceivePage() {
  return <ReceiveContent />;
}
